// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(0) && recipient != address(c) && recipient != address(this));
        vm.deal(address(c), amount);
        uint256 recipientBefore = recipient.balance;
        uint256 contractBefore = address(c).balance;
        vm.prank(address(this));
        try c.withdrawAll(recipient) {} catch {}
        uint256 recipientAfter = recipient.balance;
        uint256 contractAfter = address(c).balance;
        assertTrue(
            (contractBefore == contractAfter) ||
            (recipientAfter - recipientBefore == contractBefore - contractAfter)
        );
    }
}
